  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- the-crazy-store-pinelands (owner)
UPDATE businesses SET description = 'The Crazy Store at Howard Centre in Pinelands is a branch of the South African value and variety chain, known for packing its shelves with useful and fun items at low prices. Shoppers often find more than they came for as they browse the aisles.

The range covers practical homeware, kitchen gadgets and plastic storage containers, alongside party supplies for birthdays and seasonal celebrations, colourful toys, novelty items and basic stationery for school and the office. Because stock changes regularly, there is usually something new to discover on each visit. The aisles are neatly organised, staff are friendly and helpful, and the prices make it easy to pick up gifts, party packs or household bits without spending much. For Pinelands families, it is a handy stop for everyday essentials and small treats. The Crazy Store is at Shops G44 and G45, Howard Centre, Pinelands.', description_enriched_at = datetime('now') WHERE slug = 'the-crazy-store-pinelands' AND description = 'The Crazy Store is a variety and homeware retailer inside Howard Centre, Pinelands.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
